What number is the arrow pointing to?
[tikz]
\begin{tikzpicture}
\draw[{Stealth}-{Stealth}] (-3.4,0)--(3.4,0);
\foreach \v in {-12,...,12} {\draw (0.25*\v,0.12)--(0.25*\v,-0.12);}
\foreach \v in {-12,-6,0,6,12} {\node[below] at (0.25*\v,-0.16) {$\v$};}
\draw[-{Stealth}] (-2.0,0.62)--(-2.0,0.14);
\end{tikzpicture}
[/tikz]

